// Tests for the embedded UI build (docs/UI.md, "Build and embedding"): the
// table generated by cmake/embed_ui.cmake from the Vite output.

#include "micros3/ui_assets.h"

#include <gtest/gtest.h>

#include <algorithm>
#include <cctype>
#include <set>
#include <string>
#include <string_view>

namespace {

using micros3::ui::Asset;
using micros3::ui::embedded_assets;

bool ends_with(std::string_view text, std::string_view suffix) {
    return text.size() >= suffix.size() && text.substr(text.size() - suffix.size()) == suffix;
}

TEST(UiAssets, IndexHtmlIsEmbedded) {
    const Asset *index = embedded_assets().find("/index.html");
    ASSERT_NE(index, nullptr);
    EXPECT_EQ(index->content_type, "text/html; charset=utf-8");
    EXPECT_GT(index->size, 0u);
    const std::string_view html = index->bytes();
    EXPECT_NE(html.find("<div id=\"root\">"), std::string_view::npos);
    // The built page loads its script from /assets/, not the source tree.
    EXPECT_NE(html.find("/assets/"), std::string_view::npos);
    EXPECT_EQ(html.find("/src/main.tsx"), std::string_view::npos);
}

TEST(UiAssets, ScriptsAndStylesHaveTheirTypes) {
    bool script = false;
    bool style = false;
    for (const Asset &asset : embedded_assets()) {
        if (ends_with(asset.path, ".js")) {
            script = true;
            EXPECT_EQ(asset.content_type, "text/javascript; charset=utf-8") << asset.path;
        } else if (ends_with(asset.path, ".css")) {
            style = true;
            EXPECT_EQ(asset.content_type, "text/css; charset=utf-8") << asset.path;
        }
    }
    EXPECT_TRUE(script);
    EXPECT_TRUE(style);
}

TEST(UiAssets, PathsAreSortedAndSane) {
    const auto assets = embedded_assets();
    ASSERT_GT(assets.count, 1u);
    for (const Asset &asset : assets) {
        EXPECT_EQ(asset.path.substr(0, 1), "/") << asset.path;
        EXPECT_EQ(asset.path.find(".."), std::string_view::npos) << asset.path;
        EXPECT_EQ(asset.path.find('\\'), std::string_view::npos) << asset.path;
    }
    EXPECT_TRUE(std::is_sorted(assets.begin(), assets.end(),
                               [](const Asset &a, const Asset &b) { return a.path < b.path; }));
    // Every entry is found by its own path.
    for (const Asset &asset : assets) EXPECT_EQ(assets.find(asset.path), &asset);
    EXPECT_EQ(assets.find("/no/such/file"), nullptr);
}

// The embedded build names no external URL (U21), so the page loads nothing
// from anywhere but the binary. The build's own check
// (ui/scripts/check-safety.mjs) is stricter; this one guards the bytes that
// were actually compiled in. The allowed strings are identifiers and example
// text that are never fetched.
TEST(UiAssets, NoExternalUrls) {
    const std::set<std::string_view> allowed = {
        "http://www.w3.org/2000/svg",
        "http://www.w3.org/1999/xlink",
        "http://www.w3.org/1999/xhtml",
        "http://www.w3.org/XML/1998/namespace",
        "http://www.w3.org/1998/Math/MathML",
        "http://s3.amazonaws.com/doc/2006-03-01/",
        "https://react.dev/errors/",
        "http://localhost:5173",
        "https://*.example.com",
    };
    const auto ends_url = [](char c) {
        return std::isspace(static_cast<unsigned char>(c)) || std::string_view("\"'`()<>\\").find(c) != std::string_view::npos;
    };
    for (const Asset &asset : embedded_assets()) {
        const std::string_view text = asset.bytes();
        for (const std::string_view scheme : {"http://", "https://"}) {
            for (std::size_t at = text.find(scheme); at != std::string_view::npos; at = text.find(scheme, at + 1)) {
                std::size_t end = at + scheme.size();
                while (end < text.size() && !ends_url(text[end])) ++end;
                const std::string_view url = text.substr(at, end - at);
                EXPECT_TRUE(allowed.count(url) == 1) << asset.path << " names " << url;
            }
        }
    }
}

} // namespace
